<?php
require_once '../config/db.php';
require_once '../includes/auth.php';
require_role(['Admin']);

$campaigns = $pdo->query("SELECT campaign_applications.id, campaign_applications.application_number, campaign_applications.status, campaign_applications.property_id, lottery_campaigns.campaign_type, lottery_campaigns.lottery_name, properties.property_code FROM campaign_applications INNER JOIN lottery_campaigns ON lottery_campaigns.id = campaign_applications.campaign_id LEFT JOIN properties ON properties.id = campaign_applications.property_id WHERE campaign_applications.status IN ('Assigned','Approved') ORDER BY campaign_applications.created_at DESC")->fetchAll();
$mutations = $pdo->query("SELECT id, reference_number, status, property_id FROM citizen_requests WHERE request_type = 'Mutation' AND status = 'Approved' ORDER BY created_at DESC")->fetchAll();
$kyc = $pdo->query("SELECT id, reference_number, status, property_id FROM citizen_requests WHERE request_type = 'KYC' AND status = 'Approved' ORDER BY created_at DESC")->fetchAll();
?>
<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Property Management</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/css/style.css" rel="stylesheet"></head>
<body><div class="portal-wrapper"><header class="portal-header"><div class="portal-brand"><span>🏠</span><span>Property Management</span></div><div class="portal-header-actions"><a href="admin.php" class="btn btn-sm btn-outline-light">Dashboard</a><a href="../logout.php" class="btn btn-sm btn-light">Logout</a></div></header><main class="portal-main"><div class="portal-page-header"><h1 class="portal-page-title">Property Management</h1><p class="portal-page-subtitle">Manage properties and reverse decisions when required.</p></div><div class="mb-4"><a href="properties.php" class="btn btn-primary">My Properties</a> <a href="configuration.php" class="btn btn-outline-primary">Configuration</a></div><div class="row g-4"><div class="col-12"><div class="dashboard-shell"><h5>Assigned Lottery / Auction Properties</h5><div class="table-responsive"><table class="table table-sm"><thead><tr><th>S.No.</th><th>Application</th><th>Type</th><th>Campaign</th><th>Property</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach ($campaigns as $serial => $item): ?><tr><td><?= $serial + 1 ?></td><td><?= htmlspecialchars($item['application_number']) ?></td><td><?= htmlspecialchars($item['campaign_type']) ?></td><td><?= htmlspecialchars($item['lottery_name']) ?></td><td><?= htmlspecialchars($item['property_code'] ?: '-') ?></td><td><?= htmlspecialchars($item['status']) ?></td><td><form method="post" action="configuration.php"><input type="hidden" name="action" value="revert"><input type="hidden" name="type" value="campaign"><input type="hidden" name="request_id" value="<?= $item['id'] ?>"><button class="btn btn-sm btn-outline-warning">Revert</button></form></td></tr><?php endforeach; ?><?php if (!$campaigns): ?><tr><td colspan="7" class="text-center text-muted">No assigned campaign properties.</td></tr><?php endif; ?></tbody></table></div></div></div><div class="col-lg-6"><div class="dashboard-shell"><h5>Approved Mutations</h5><table class="table table-sm"><thead><tr><th>S.No.</th><th>Reference</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach ($mutations as $serial => $item): ?><tr><td><?= $serial + 1 ?></td><td><?= htmlspecialchars($item['reference_number']) ?></td><td><?= htmlspecialchars($item['status']) ?></td><td><form method="post" action="configuration.php"><input type="hidden" name="action" value="revert"><input type="hidden" name="type" value="mutation"><input type="hidden" name="request_id" value="<?= $item['id'] ?>"><button class="btn btn-sm btn-outline-warning">Revert</button></form></td></tr><?php endforeach; ?><?php if (!$mutations): ?><tr><td colspan="4" class="text-center text-muted">No approved mutations.</td></tr><?php endif; ?></tbody></table></div></div><div class="col-lg-6"><div class="dashboard-shell"><h5>Approved KYC</h5><table class="table table-sm"><thead><tr><th>S.No.</th><th>Reference</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach ($kyc as $serial => $item): ?><tr><td><?= $serial + 1 ?></td><td><?= htmlspecialchars($item['reference_number']) ?></td><td><?= htmlspecialchars($item['status']) ?></td><td><form method="post" action="configuration.php"><input type="hidden" name="action" value="revert"><input type="hidden" name="type" value="kyc"><input type="hidden" name="request_id" value="<?= $item['id'] ?>"><button class="btn btn-sm btn-outline-warning">Revert</button></form></td></tr><?php endforeach; ?><?php if (!$kyc): ?><tr><td colspan="4" class="text-center text-muted">No approved KYC requests.</td></tr><?php endif; ?></tbody></table></div></div></div></main></div></body></html>
